def get_file_hash(filename: Union[str, Path]) -> Tuple[str, str]:
    """Read the contents of a file and return it together with a content based hash (md5).

    Returns a tuple of (content, hash), where content is the text content of the file,
    and hash is an md5 hash of the raw bytes. The hash can be used for cache busting,
    e.g. as a query parameter in a url, so that the browser will fetch the file again
    when its contents change.
    """
    with open(filename, "rb") as f:
        data = f.read()
    if sys.version_info >= (3, 9):
        hash = hashlib.new("md5", data=data)
    else:
        hash = hashlib.new("md5", data)
    return data.decode("utf-8"), hash.hexdigest()

