for root, _dirs, files in os.walk("/root/.cache/pip/http-v2"):
    for f in files:
        if not f.endswith(".body"):
            continue
        path = os.path.join(root, f)
        if os.path.getsize(path) == 0:
            continue
        try:
            with open(path, "rb") as fh:
                data = fh.read(4)
            if data[:2] == b"PK":
                with zipfile.ZipFile(path) as z:
                    wheel_info = [n for n in z.namelist() if n.endswith(".dist-info/WHEEL")]
                    if not wheel_info:
                        continue
                    info = z.read(wheel_info[0]).decode()

                    def get(field):
                        m = re.search(r"^%s:\s*(.+)$" % field, info, re.M)
                        return m.group(1).strip() if m else None

                    name = get("Name").replace("-", "_")
                    version = get("Version")
                    tags = [t for t in re.findall(r"^Tag:\s*(.+)$", info, re.M)]
                    py_tags = set()
                    abi_tags = set()
                    plat_tags = set()
                    for t in tags:
                        parts = t.split("-")
                        py_tags.add(parts[0])
                        abi_tags.add(parts[1])
                        plat_tags.add(parts[2])
                    fn = "%s-%s" % (name, version)
                    if get("Root-Is-Purelib") == "true":
                        fn += "-py2.py3-none-any.whl"
                    else:
                        fn += "-%s-%s-%s.whl" % (sorted(py_tags)[0], sorted(abi_tags)[0], sorted(plat_tags)[0])
                    results.append((name, version, fn, path))
            elif data == b"\x1f\x8b":
                tf = tarfile.open(path, "r:gz")
                top = tf.getnames()[0]
                name = top.split("-")[0]
                version = top[len(top.split("-")[0]) + 1 :]
                results.append((name, version, os.path.basename(path) + ".tar.gz", path))
        except Exception:
            pass

os.makedirs("/tmp/opencode/wheelhouse", exist_ok=True)
seen = {}
copied = 0
for name, version, fn, path in sorted(results):
    dest = os.path.join("/tmp/opencode/wheelhouse", fn)
    if name not in seen:
        seen[name] = fn
    if os.path.exists(dest):
        continue
    shutil.copy(path, dest)
    copied += 1
print("total artifacts:", len(results))
print("copied:", copied)
print("distinct packages:", len(seen))
for k, v in sorted(seen.items()):
    print(f"{k} -> {v}")

