from typing import Any, Callable, Dict, Optional, TypeVar, Union

import asyncio
import dataclasses
import enum
import functools
import inspect
import logging
import threading

import solara

logger = logging.getLogger("solara.tasks")

T = TypeVar("T")
U = TypeVar("U")

_loop: Optional[asyncio.AbstractEventLoop] = None
_loop_lock = threading.Lock()


def _is_coroutine_function(f: Callable) -> bool:
    while isinstance(f, functools.partial):
        f = f.func
    return inspect.iscoroutinefunction(f)


def _get_loop() -> asyncio.AbstractEventLoop:
    global _loop
    if _loop is None or _loop.is_closed():
        with _loop_lock:
            if _loop is None or _loop.is_closed():
                loop = asyncio.new_event_loop()
                thread = threading.Thread(target=asyncio.set_event_loop, args=(loop,), daemon=True)
                thread.start()

                def run_loop():
                    loop.run_forever()

                thread = threading.Thread(target=run_loop, daemon=True)
                thread.start()
                _loop = loop
    return _loop


def _run_awaitable_sync(awaitable):
    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(awaitable)
    finally:
        loop.close()


class TaskState(enum.Enum):
    """The state of a task run.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    The task can be in one of the following states:

     * `NOTCALLED`: The task has not been called (yet).
     * `STARTING`: The task has started.
     * `WAITING`: The task is waiting for another run of the same task to finish.
     * `RUNNING`: The task is running.
     * `ERROR`: The task raised an exception.
     * `FINISHED`: The task finished successfully.
     * `CANCELLED`: The task was cancelled.
    """

    NOTCALLED = 1
    STARTING = 2
    WAITING = 3
    RUNNING = 4
    ERROR = 5
    FINISHED = 6
    CANCELLED = 7


@dataclasses.dataclass(frozen=True)
class TaskResult(Generic[T]):
    """The result of a task run.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    A `TaskResult` is a frozen dataclass, and can be seen as a snapshot of the
    state of a task. The [Task](/api/task) class (and the `use_task` hook) exposes
    a reactive version of this object, see for instance the `result` property.

    ## Attributes

     * `value`: The value of the run, this will be set to the return value of the
       function when the task finished successfully, `None` otherwise.
     * `latest`: The latest (successful) value of the task, even if a later run
       failed or was cancelled.
     * `exception`: The exception raised by the run, if any.
     * `state`: The [state](/api/task#TaskState) of the run.
     * `progress`: A number between 0 and 1, or `None` if progress was not reported.
    """

    value: Optional[T] = None
    latest: Optional[T] = None
    exception: Optional[BaseException] = None
    state: TaskState = TaskState.NOTCALLED
    progress: Optional[float] = None

    def __or__(self, next: Callable[["TaskResult[T]"], "TaskResult[U]"]) -> "TaskResult[U]":  # type: ignore
        return next(self)  # type: ignore

    @property
    def result(self) -> Optional[T]:
        """The value of the result, same as `value`."""
        return self.value

    @property
    def pending(self) -> bool:
        """True if the task started, but has not reached a final state yet."""
        return self.state in (TaskState.STARTING, TaskState.WAITING, TaskState.RUNNING)

    @property
    def not_called(self) -> bool:
        """True if the task has not been called yet."""
        return self.state == TaskState.NOTCALLED

    @property
    def cancelled(self) -> bool:
        """True if the task was cancelled."""
        return self.state == TaskState.CANCELLED

    @property
    def error(self) -> bool:
        """True if the task raised an exception."""
        return self.state == TaskState.ERROR

    @property
    def finished(self) -> bool:
        """True if the task finished successfully."""
        return self.state == TaskState.FINISHED


class Task(Generic[T]):
    """A task is an asynchronous wrapper around a (sync or async) function.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    A `Task` can be created with the [`task`](/api/task) decorator, or with the
    [`use_task`](/api/use_task) hook. See those pages for examples.

    A task can be called (from anywhere, for instance an event handler) like a
    regular function, and will execute the wrapped function. Depending on the
    wrapped function being a coroutine function or not, it will be executed in
    an asyncio event loop, or in a separate thread (so the UI will not block).

    The task keeps track of the state of the run, and reports progress and
    results through reactive variables, so components using them will
    automatically update (e.g. using [solara.Markdown](/api/markdown)).

    Only one run of a task can be active at the same time; calling the task
    while it is running will cancel the current run and start a new one.
    """

    def __new__(cls, task_func, *args, **kwargs):
        if cls is Task:
            if _is_coroutine_function(task_func):
                return object.__new__(AsyncTask)
            return object.__new__(ThreadTask)
        return super().__new__(cls)

    def __init__(self, task_func: Union[Callable[..., T], Callable[..., Any]], arguments: Optional[Dict[str, Any]] = None) -> None:
        self._task_func = task_func
        self._task_func_sig = inspect.signature(task_func)
        self.__name__ = getattr(task_func, "__name__", None)
        if arguments:
            self._arguments = arguments
        self._result: solara.Reactive[TaskResult[T]] = solara.Reactive(TaskResult[T]())
        self._lock = threading.RLock()
        # increased for every run, used to ignore results of older runs
        self._run_counter = 0
        self._cancel_event: Optional[threading.Event] = None
        self._running_thread: Optional[threading.Thread] = None
        self._async_task: Optional[Any] = None

    # these marker objects are used to know when an object has
    # not yet been set (and distinguish from None)
    NOT_SET = object()

    # current state of the task
    @property
    def result(self) -> "solara.Reactive[TaskResult[T]]":
        """A reactive variable with the [TaskResult](/api/task#TaskResult) of the task.

        This can be used directly in components, or read using the other
        properties, which are all derived from this.
        """
        return self._result

    @property
    def state(self) -> TaskState:
        """The [state](/api/task#TaskState) of the current run."""
        return self._result.value.state

    @property
    def value(self) -> Optional[T]:
        """The value of the current run, `None` until the task finished successfully."""
        return self._result.value.value

    @property
    def latest(self) -> Optional[T]:
        """The latest successful value of the task.

        Unlike `value`, this will keep the value of the last successful run,
        even if a later run failed or is still running.
        """
        return self._result.value.latest

    @property
    def exception(self) -> Optional[BaseException]:
        """The exception of the current run, `None` unless the run failed."""
        return self._result.value.exception

    @property
    def progress(self) -> Optional[float]:
        """The progress of the current run, a number between 0 and 1.

        `None` if no progress was reported (see [`task`](/api/task)).
        """
        return self._result.value.progress

    @property
    def pending(self) -> bool:
        """True if the task started, but has not reached a final state yet."""
        return self._result.value.pending

    @property
    def not_called(self) -> bool:
        """True if the task has not been called yet."""
        return self._result.value.not_called

    @property
    def cancelled(self) -> bool:
        """True if the task was cancelled."""
        return self._result.value.cancelled

    @property
    def error(self) -> bool:
        """True if the task raised an exception."""
        return self._result.value.error

    @property
    def finished(self) -> bool:
        """True if the task finished successfully."""
        return self._result.value.finished

    def __repr__(self):
        if self.__name__ is not None:
            return f"<Task {self.__name__} state={self.state.value}>"
        return f"<Task state={self.state.value}>"

    def __call__(self, *args, **kwargs) -> "Task[T]":
        """Start a new run of the task, return the task itself.

        Will cancel and supersede a previously active run. The task function
        may declare a `progress` and/or a `cancel` parameter (in any position)
        that will be provided by the framework.

        ## Arguments

         * `*args`, `**kwargs`: The arguments to pass to the wrapped function.
        """
        try:
            bound_partial = self._task_func_sig.bind_partial(*args, **kwargs)
        except TypeError as e:
            raise TypeError(f"Invalid arguments {args!r} {kwargs!r} for task {self.__name__}: {e}") from e

        with self._lock:
            # cancel any previous run, we only allow one active run at the time
            if self._cancel_event is not None:
                self._cancel_event.set()
            self._run_counter += 1
            run_counter = self._run_counter
            old_async_task = self._async_task
            self._async_task = None
        if old_async_task is not None and not old_async_task.done():
            old_async_task.cancel()
        self._set_result(TaskState.STARTING, run_counter=run_counter)

        cancel_event = threading.Event()
        inject = {}
        if "progress" in self._task_func_sig.parameters and "progress" not in bound_partial.arguments:
            inject["progress"] = self._set_progress(run_counter)
        if "cancel" in self._task_func_sig.parameters and "cancel" not in bound_partial.arguments:
            inject["cancel"] = cancel_event
        try:
            bound = self._task_func_sig.bind(*args, **kwargs, **inject)
        except TypeError as e:
            raise TypeError(f"Invalid arguments {args!r} {kwargs!r} for task {self.__name__}: {e}") from e
        self._cancel_event = cancel_event
        self._launch(bound, cancel_event, run_counter)
        return self

    def cancel(self) -> None:
        """Cancel the current run, if one is active.

        For tasks running in a thread, the function should either poll the
        `cancel` event (if it declared a `cancel` parameter), or it will be
        cancelled at the next executed line of Python code. For `async`
        tasks, the coroutine will be cancelled (raising `asyncio.CancelledError`).
        """
        with self._lock:
            if self._cancel_event is not None:
                self._cancel_event.set()
            async_task = self._async_task
        if async_task is not None and not async_task.done():
            async_task.cancel()

    # abstract, implemented by ThreadTask/AsyncTask
    def _launch(self, bound, cancel_event, run_counter):
        raise NotImplementedError

    def _set_result(self, state, value=None, exception=None, run_counter=None):
        with self._lock:
            if run_counter is not None and run_counter != self._run_counter:
                # result of an outdated run, ignore
                return
            current = self._result.get(add_watch=False)
            if state == TaskState.FINISHED:
                new = TaskResult[T](value=value, latest=value, state=state, progress=current.progress)
            elif state == TaskState.ERROR:
                new = TaskResult[T](exception=exception, latest=current.latest, state=state)
            elif state == TaskState.CANCELLED:
                new = TaskResult[T](latest=current.latest, state=state)
            else:
                new = TaskResult[T](latest=current.latest, state=state)
            self._result.set(new)

    def _set_progress(self, run_counter):
        def handler(progress_value: float):
            with self._lock:
                if run_counter != self._run_counter:
                    return
                current = self._result.get(add_watch=False)
                self._result.set(dataclasses.replace(current, progress=progress_value))

        return handler

    @staticmethod
    def _get_kernel_context():
        try:
            import solara.server.kernel_context

            return solara.server.kernel_context.get_current_context()
        except Exception:  # noqa
            return None


class ThreadTask(Task[T]):
    """A task that runs the wrapped function in a separate thread.

    See the [task](/api/task) page for more information.
    """

    def _launch(self, bound, cancel_event, run_counter):
        thread = threading.Thread(target=self._run_thread, args=(bound, cancel_event, run_counter), daemon=True)
        thread.start()

    def _run_thread(self, bound, cancel_event, run_counter):
        context = self._get_kernel_context()
        wait_thread = None
        with self._lock:
            if self._running_thread is not None and self._running_thread.is_alive():
                wait_thread = self._running_thread
            self._running_thread = threading.current_thread()
        if wait_thread is not None:
            self._set_result(TaskState.WAITING, run_counter=run_counter)
            try:
                wait_thread.join()
            except BaseException:  # noqa
                pass
            if run_counter != self._run_counter:
                return
        self._set_result(TaskState.RUNNING, run_counter=run_counter)
        try:
            if context is not None:
                with context:
                    self._execute(bound, cancel_event)
            else:
                self._execute(bound, cancel_event)
        finally:
            with self._lock:
                if self._running_thread is threading.current_thread():
                    self._running_thread = None
            if cancel_event.is_set():
                current = self._result.get(add_watch=False)
                if current.state not in (TaskState.FINISHED, TaskState.ERROR):
                    self._set_result(TaskState.CANCELLED, run_counter=run_counter)

    def _execute(self, bound, cancel_event):
        try:
            with solara.util.cancel_guard(cancel_event):
                value = self._task_func(*bound.args, **bound.kwargs)
            if inspect.isawaitable(value):
                value = _run_awaitable_sync(value)
            self._set_result(TaskState.FINISHED, value=value, run_counter=self._run_counter)
        except solara.util.CancelledError:
            self._set_result(TaskState.CANCELLED, run_counter=self._run_counter)
        except Exception as e:
            logger.exception(f"An exception occurred in task {self.__name__}")
            self._set_result(TaskState.ERROR, exception=e, run_counter=self._run_counter)


class AsyncTask(Task[T]):
    """A task that runs the wrapped (coroutine) function in an asyncio event loop.

    See the [task](/api/task) page for more information.
    """

    def _launch(self, bound, cancel_event, run_counter):
        loop = _get_loop()
        future = asyncio.run_coroutine_threadsafe(self._run_async(bound, cancel_event, run_counter), loop)
        with self._lock:
            self._async_task = future

        def _on_done(done_future):
            with self._lock:
                if self._async_task is done_future:
                    self._async_task = None

        future.add_done_callback(_on_done)

    async def _run_async(self, bound, cancel_event, run_counter):
        try:
            previous = None
            with self._lock:
                previous = self._async_task
            if previous is not None and not previous.done():
                self._set_result(TaskState.WAITING, run_counter=run_counter)
                while not previous.done() and run_counter == self._run_counter:
                    try:
                        await asyncio.wait_for(asyncio.shield(asyncio.wrap_future(previous)), timeout=0.05)
                        break
                    except asyncio.TimeoutError:
                        continue
                    except asyncio.CancelledError:
                        if previous.done():
                            break
                        raise
            if run_counter != self._run_counter:
                return
            self._set_result(TaskState.RUNNING, run_counter=run_counter)
            value = self._task_func(*bound.args, **bound.kwargs)
            if inspect.isawaitable(value):
                value = await value
            self._set_result(TaskState.FINISHED, value=value, run_counter=run_counter)
        except asyncio.CancelledError:
            self._set_result(TaskState.CANCELLED, run_counter=run_counter)
        except Exception as e:
            logger.exception(f"An exception occurred in task {self.__name__}")
            self._set_result(TaskState.ERROR, exception=e, run_counter=run_counter)


def task(task_func: Optional[Callable[..., T]] = None) -> Union[Task[T], Callable[[Callable[..., T]], Task[T]]]:
    """A decorator around a function, turning it into a [Task](/api/task).

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    A task is a wrapper around a (sync or async) function, that can be called
    from anywhere in your application (for instance from an event handler),
    and will execute the function without blocking the UI. The state and
    result of the task can be inspected (reactively) via the returned
    [Task](/api/task) object.

    The task can be called like a regular function, with the arguments of the
    wrapped function. The task function may declare a `progress` and/or a
    `cancel` parameter that will be provided by the framework. The `progress`
    callback can be called with a number between 0 and 1 to report progress,
    and the `cancel` parameter is a `threading.Event` that will be set when
    the task is cancelled.

    ## Example

    ```solara
    import time
    import solara
    import solara.lab as lab


    @lab.task
    def calculate(progress):
        total = 0
        for i in range(100):
            time.sleep(0.1)
            total += i
            progress(i / 100)
        return total


    @solara.component
    def Page():
        task = calculate
        task()
        with solara.Column():
            solara.Markdown(f"**Running:** {task.pending}")
            solara.Markdown(f"**Progress:** {task.progress}")
            solara.Markdown(f"**Result:** {task.value}")
    ```
    """
    if task_func is not None:
        return _make_task(task_func)

    def decorator(func: Callable[..., T]) -> Task[T]:
        return _make_task(func)

    return decorator


def _make_task(task_func: Callable[..., T]) -> Task[T]:
    if _is_coroutine_function(task_func):
        return AsyncTask[T](task_func)
    return ThreadTask[T](task_func)


def use_task(task_func: Callable[..., T]) -> Task[T]:
    """A hook that returns a [Task](/api/task), scoped to the current component instance.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    Unlike the [`task`](/api/task) decorator, which creates a task that is
    shared (module level, or 'global'), this hook creates a task that is
    unique to the current component instance. This is useful if you want to
    (re)use the same function in multiple component instances, but want each
    instance to have its own task state and results.

    The task can be called like a regular function, for instance from an
    event handler. The task function may declare a `progress` and/or a
    `cancel` parameter that will be provided by the framework.

    ## Example

    ```solara
    import time
    import solara
    import solara.lab as lab


    def calculate(progress):
        time.sleep(1)
        progress(1.0)
        return 42


    @solara.component
    def Page():
        # each Page instance will have its own task
        task = lab.use_task(calculate)

        def on_click():
            task()

        solara.Button("Start", on_click=on_click)
        with solara.Column():
            if task.error:
                solara.Error(str(task.exception))
            elif task.running:
                solara.Info(f"Running, progress: {task.progress}")
            else:
                solara.Markdown(f"**Result:** {task.value}")
    ```
    """
    task = solara.use_memo(lambda: _make_task(task_func), [])
    return task  # type: ignore

import asyncio
import dataclasses
import enum
import functools
import inspect
import logging
import threading
from typing import Any, Callable, Dict, Generic, Optional, TypeVar, Union

import solara

logger = logging.getLogger("solara.tasks")

T = TypeVar("T")
U = TypeVar("U")

_loop: Optional[asyncio.AbstractEventLoop] = None
_loop_lock = threading.Lock()


def _is_coroutine_function(f: Callable) -> bool:
    while isinstance(f, functools.partial):
        f = f.func
    return inspect.iscoroutinefunction(f)


def _get_loop() -> asyncio.AbstractEventLoop:
    global _loop
    if _loop is None or _loop.is_closed():
        with _loop_lock:
            if _loop is None or _loop.is_closed():
                loop = asyncio.new_event_loop()

                def run_loop():
                    loop.run_forever()

                thread = threading.Thread(target=run_loop, daemon=True)
                thread.start()
                _loop = loop
    return _loop


def _run_awaitable_sync(awaitable):
    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(awaitable)
    finally:
        loop.close()


class TaskState(enum.Enum):
    """The state of a task run.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    The task can be in one of the following states:

     * `NOTCALLED`: The task has not been called (yet).
     * `STARTING`: The task has started.
     * `WAITING`: The task is waiting for another run of the same task to finish.
     * `RUNNING`: The task is running.
     * `ERROR`: The task raised an exception.
     * `FINISHED`: The task finished successfully.
     * `CANCELLED`: The task was cancelled.
    """

    NOTCALLED = 1
    STARTING = 2
    WAITING = 3
    RUNNING = 4
    ERROR = 5
    FINISHED = 6
    CANCELLED = 7


@dataclasses.dataclass(frozen=True)
class TaskResult(Generic[T]):
    """The result of a task run.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    A `TaskResult` is a frozen dataclass, and can be seen as a snapshot of the
    state of a task. The [Task](/api/task) class (and the `use_task` hook)
    exposes a reactive version of this object, see for instance the `result`
    property.

    ## Attributes

     * `value`: The value of the run, this will be set to the return value of
       the function when the task finished successfully, `None` otherwise.
     * `latest`: The latest (successful) value of the task, even if a later run
       failed or was cancelled.
     * `exception`: The exception raised by the run, if any.
     * `state`: The [state](/api/task#TaskState) of the run.
     * `progress`: A number between 0 and 1, or `None` if progress was not
       reported.
    """

    value: Optional[T] = None
    latest: Optional[T] = None
    exception: Optional[BaseException] = None
    state: TaskState = TaskState.NOTCALLED
    progress: Optional[float] = None

    def __or__(self, next: Callable[["TaskResult[T]"], "TaskResult[U]"]) -> "TaskResult[U]":
        return next(self)

    @property
    def result(self) -> Optional[T]:
        """The value of the result, same as `value`."""
        return self.value

    @property
    def pending(self) -> bool:
        """True if the task started, but has not reached a final state yet."""
        return self.state in (TaskState.STARTING, TaskState.WAITING, TaskState.RUNNING)

    @property
    def not_called(self) -> bool:
        """True if the task has not been called yet."""
        return self.state == TaskState.NOTCALLED

    @property
    def cancelled(self) -> bool:
        """True if the task was cancelled."""
        return self.state == TaskState.CANCELLED

    @property
    def error(self) -> bool:
        """True if the task raised an exception."""
        return self.state == TaskState.ERROR

    @property
    def finished(self) -> bool:
        """True if the task finished successfully."""
        return self.state == TaskState.FINISHED


class Task(Generic[T]):
    """A task is an asynchronous wrapper around a (sync or async) function.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    A `Task` can be created with the [`task`](/api/task) decorator, or with
    the [`use_task`](/api/use_task) hook. See those pages for examples.

    A task can be called (from anywhere, for instance an event handler) like a
    regular function, and will execute the wrapped function. Depending on the
    wrapped function being a coroutine function or not, it will be executed in
    an asyncio event loop, or in a separate thread (so the UI will not block).

    The task keeps track of the state of the run, and reports progress and
    results through reactive variables, so components using them will
    automatically update (e.g. using [solara.Markdown](/api/markdown)).

    Only one run of a task can be active at the same time; calling the task
    while it is running will cancel the current run and start a new one.
    """

    def __new__(cls, task_func, *args, **kwargs):
        if cls is Task:
            if _is_coroutine_function(task_func):
                return object.__new__(AsyncTask)
            return object.__new__(ThreadTask)
        return super().__new__(cls)

