        self._task_func = task_func
        self._task_func_sig = inspect.signature(task_func)
        self.__name__ = getattr(task_func, "__name__", None)
        self._result: solara.Reactive[TaskResult[T]] = solara.Reactive(TaskResult[T]())
        self._lock = threading.RLock()
        # increased for every run, used to ignore results of outdated runs
        self._run_counter = 0
        self._cancel_event: Optional[threading.Event] = None
        self._running_thread: Optional[threading.Thread] = None
        self._async_task: Optional[Any] = None

    @property
    def result(self) -> "solara.Reactive[TaskResult[T]]":
        """A reactive variable with the [TaskResult](/api/task#TaskResult) of the task.

        This can be used directly in components, or read using the other
        properties, which are all derived from this.
        """
        return self._result

    @property
    def state(self) -> TaskState:
        """The [state](/api/task#TaskState) of the current run."""
        return self._result.value.state

    @property
    def value(self) -> Optional[T]:
        """The value of the current run, `None` until the task finished successfully."""
        return self._result.value.value

    @property
    def latest(self) -> Optional[T]:
        """The latest successful value of the task.

        Unlike `value`, this will keep the value of the last successful run,
        even if a later run failed or is still running.
        """
        return self._result.value.latest

    @property
    def exception(self) -> Optional[BaseException]:
        """The exception of the current run, `None` unless the run failed."""
        return self._result.value.exception

    @property
    def progress(self) -> Optional[float]:
        """The progress of the current run, a number between 0 and 1.

        `None` if no progress was reported (see [`task`](/api/task)).
        """
        return self._result.value.progress

    @property
    def pending(self) -> bool:
        """True if the task started, but has not reached a final state yet."""
        return self._result.value.pending

    @property
    def not_called(self) -> bool:
