class AsyncTask(Task[T]):
    """A task that runs the wrapped (coroutine) function in an asyncio event loop.

    See the [task](/api/task) page for more information.
    """

    def _launch(self, bound, cancel_event, run_counter):
        loop = _get_loop()
        future = asyncio.run_coroutine_threadsafe(self._run_async(bound, cancel_event, run_counter), loop)
        with self._lock:
            self._async_task = future

        def _on_done(done_future):
            with self._lock:
                if self._async_task is done_future:
                    self._async_task = None

        future.add_done_callback(_on_done)

    async def _run_async(self, bound, cancel_event, run_counter):
        try:
            previous = None
            with self._lock:
                previous = self._async_task
            if previous is not None and not previous.done():
                self._set_result(TaskState.WAITING, run_counter=run_counter)
                while not previous.done() and run_counter == self._run_counter:
                    try:
                        await asyncio.wait_for(asyncio.shield(asyncio.wrap_future(previous)), timeout=0.05)
                        break
                    except asyncio.TimeoutError:
                        continue
                    except asyncio.CancelledError:
                        if previous.done():
                            break
                        raise
            if run_counter != self._run_counter:
                return
            self._set_result(TaskState.RUNNING, run_counter=run_counter)
            value = self._task_func(*bound.args, **bound.kwargs)
            if inspect.isawaitable(value):
                value = await value
            self._set_result(TaskState.FINISHED, value=value, run_counter=run_counter)
        except asyncio.CancelledError:
            self._set_result(TaskState.CANCELLED, run_counter=run_counter)
        except Exception as e:
            logger.exception(f"An exception occurred in task {self.__name__}")
            self._set_result(TaskState.ERROR, exception=e, run_counter=run_counter)


def task(task_func: Optional[Callable[..., T]] = None) -> Union[Task[T], Callable[[Callable[..., T]], Task[T]]]:
    """A decorator around a function, turning it into a [Task](/api/task).

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    A task is a wrapper around a (sync or async) function, that can be called
    from anywhere in your application (for instance from an event handler),
    and will execute the function without blocking the UI. The state and
    result of the task can be inspected (reactively) via the returned
    [Task](/api/task) object.

    The task can be called like a regular function, with the arguments of the
    wrapped function. The task function may declare a `progress` and/or a
    `cancel` parameter that will be provided by the framework. The `progress`
    callback can be called with a number between 0 and 1 to report progress,
    and the `cancel` parameter is a `threading.Event` that will be set when
    the task is cancelled.

    ## Example

    ```solara
    import time
    import solara
    import solara.lab as lab


    @lab.task
    def calculate(progress):
        total = 0
        for i in range(100):
            time.sleep(0.1)
            total += i
            progress(i / 100)
        return total


    @solara.component
    def Page():
        task = calculate
        task()
        with solara.Column():
            solara.Markdown(f"**Running:** {task.pending}")
            solara.Markdown(f"**Progress:** {task.progress}")
            solara.Markdown(f"**Result:** {task.value}")
    ```
    """
    if task_func is not None:
        return _make_task(task_func)

    def decorator(func: Callable[..., T]) -> Task[T]:
        return _make_task(func)

    return decorator


def _make_task(task_func: Callable[..., T]) -> Task[T]:
    if _is_coroutine_function(task_func):
        return AsyncTask[T](task_func)
    return ThreadTask[T](task_func)


def use_task(task_func: Callable[..., T]) -> Task[T]:
    """A hook that returns a [Task](/api/task), scoped to the current component instance.

    (*Note: [This API is experimental and may change in the future](/docs/lab).*)

    Unlike the [`task`](/api/task) decorator, which creates a task that is
    shared (module level, or 'global'), this hook creates a task that is
    unique to the current component instance. This is useful if you want to
    (re)use the same function in multiple component instances, but want each
    instance to have its own task state and results.

    The task can be called like a regular function, for instance from an
    event handler. The task function may declare a `progress` and/or a
    `cancel` parameter that will be provided by the framework.

    ## Example

    ```solara
    import time
    import solara
    import solara.lab as lab


    def calculate(progress):
        time.sleep(1)
        progress(1.0)
        return 42


    @solara.component
    def Page():
        # each Page instance will have its own task
        task = lab.use_task(calculate)

        def on_click():
            task()

        solara.Button("Start", on_click=on_click)
        with solara.Column():
